*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-0: #07090f;
  --bg-1: #0b0e18;
  --bg-2: #11141f;
  --ink: #f4ead5;
  --ink-2: #d4c8a8;
  --ink-dim: #9d9176;
  --ink-faint: #5e5645;
  --accent: #f0a868;
  --accent-2: #e87b4d;
  --accent-cool: #6cb4d4;
  --accent-cool-2: #4a8aa8;
  --line: rgba(244, 234, 213, 0.06);
  --line-2: rgba(244, 234, 213, 0.12);
  --line-3: rgba(244, 234, 213, 0.2);
  --serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Palatino, "Book Antiqua", Georgia, "Times New Roman", serif;
  --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
}

html, body {
  width: 1280px;
  height: 800px;
  overflow: hidden;
  font-family: var(--sans);
  color: var(--ink);
  background: var(--bg-0);
}

body {
  background-image:
    radial-gradient(ellipse 1100px 800px at 12% -10%, rgba(240, 168, 104, 0.10), transparent 55%),
    radial-gradient(ellipse 900px 700px at 88% 110%, rgba(108, 180, 212, 0.05), transparent 55%),
    linear-gradient(180deg, var(--bg-1) 0%, var(--bg-2) 100%);
  position: relative;
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='200' height='200'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='2' stitchTiles='stitch'/><feColorMatrix values='0 0 0 0 0.9  0 0 0 0 0.85  0 0 0 0 0.7  0 0 0 0.5 0'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>");
  opacity: 0.08;
  mix-blend-mode: overlay;
  z-index: 100;
}

.stage {
  width: 1280px;
  height: 800px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px;
  position: relative;
}

.card {
  width: 1200px;
  height: 720px;
  background: linear-gradient(155deg, rgba(29, 34, 49, 0.55), rgba(15, 19, 32, 0.55));
  border: 1px solid var(--line-2);
  border-radius: 22px;
  box-shadow:
    0 40px 80px -30px rgba(0, 0, 0, 0.7),
    0 0 0 1px rgba(244, 234, 213, 0.03) inset,
    0 1px 0 rgba(244, 234, 213, 0.06) inset;
  padding: 40px 56px;
  display: grid;
  grid-template-rows: auto 1fr auto;
  position: relative;
  overflow: hidden;
  backdrop-filter: blur(8px);
}

.card::after {
  content: "";
  position: absolute;
  top: -1px;
  left: 50%;
  transform: translateX(-50%);
  width: 240px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--accent), transparent);
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  padding-bottom: 22px;
  border-bottom: 1px solid var(--line);
}

.eyebrow {
  font-size: 10px;
  letter-spacing: 0.35em;
  text-transform: uppercase;
  color: var(--ink-faint);
  font-weight: 600;
}

.header-left .eyebrow { margin-bottom: 12px; }

.location {
  font-family: var(--serif);
  font-size: 56px;
  font-weight: 400;
  letter-spacing: -0.02em;
  line-height: 0.95;
  color: var(--ink);
  margin: 0;
}

.coords {
  font-family: var(--mono);
  font-size: 11px;
  color: var(--ink-dim);
  margin-top: 10px;
  letter-spacing: 0.08em;
}

.coords .sep { color: var(--ink-faint); margin: 0 8px; }

.header-right { text-align: right; }
.header-right .eyebrow { margin-bottom: 12px; }

.weekday {
  font-family: var(--serif);
  font-size: 28px;
  font-weight: 400;
  color: var(--ink);
  line-height: 1;
}

.date {
  font-family: var(--mono);
  font-size: 12px;
  color: var(--ink-dim);
  margin-top: 8px;
  letter-spacing: 0.08em;
}

.main {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 56px;
  padding: 28px 0 24px;
  align-items: center;
}

.hero {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.condition {
  display: flex;
  align-items: center;
  gap: 18px;
}

.condition .icon-wrap {
  width: 52px;
  height: 52px;
  color: var(--accent);
  flex-shrink: 0;
}

.condition .icon-wrap svg { width: 100%; height: 100%; }

.condition .label {
  font-family: var(--serif);
  font-size: 22px;
  font-weight: 400;
  color: var(--ink);
  letter-spacing: 0.005em;
}

.temp-display {
  display: flex;
  align-items: flex-start;
  gap: 4px;
  line-height: 0.82;
  margin-top: 4px;
}

.temp-display .value {
  font-family: var(--serif);
  font-size: 180px;
  font-weight: 300;
  letter-spacing: -0.06em;
  background: linear-gradient(180deg, #fbe9c8 0%, #f0a868 70%, #e87b4d 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.temp-display .unit {
  font-family: var(--serif);
  font-size: 52px;
  font-weight: 300;
  color: var(--accent);
  margin-top: 14px;
}

.temp-meta {
  font-size: 11px;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--ink-faint);
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 2px;
}

.temp-meta .dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--line-3);
}

.temp-meta .low-label { color: var(--accent-cool); }
.temp-meta .low-val {
  color: var(--ink-2);
  font-family: var(--serif);
  font-size: 14px;
  letter-spacing: 0;
  text-transform: none;
  font-weight: 400;
}

.stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  align-self: stretch;
  align-content: center;
}

.stat {
  background: linear-gradient(155deg, rgba(244, 234, 213, 0.04), rgba(244, 234, 213, 0.01));
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 18px 20px;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.stat::before {
  content: "";
  position: absolute;
  top: 14px;
  bottom: 14px;
  left: 0;
  width: 2px;
  background: var(--accent);
  border-radius: 0 1px 1px 0;
}

.stat.cool::before { background: var(--accent-cool); }
.stat.warm::before { background: var(--accent-2); }
.stat.neutral::before { background: var(--ink-dim); }

.stat .label {
  font-size: 10px;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--ink-faint);
  font-weight: 600;
  margin-bottom: 8px;
}

.stat .value {
  font-family: var(--serif);
  font-size: 34px;
  font-weight: 400;
  line-height: 1;
  color: var(--ink);
  display: flex;
  align-items: baseline;
  gap: 2px;
}

.stat .value .small {
  font-size: 16px;
  color: var(--ink-dim);
  font-weight: 300;
}

.stat .sub {
  font-family: var(--mono);
  font-size: 10px;
  color: var(--ink-faint);
  margin-top: 6px;
  letter-spacing: 0.08em;
}

.hourly {
  padding-top: 22px;
  border-top: 1px solid var(--line);
}

.hourly-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 12px;
}

.hourly-header .title {
  font-size: 10px;
  letter-spacing: 0.35em;
  text-transform: uppercase;
  color: var(--ink-faint);
  font-weight: 600;
}

.hourly-header .title .accent {
  color: var(--ink-dim);
  font-weight: 500;
  margin-left: 10px;
  letter-spacing: 0.15em;
}

.hourly-header .sub {
  font-family: var(--mono);
  font-size: 10px;
  color: var(--ink-faint);
  letter-spacing: 0.08em;
}

.chart-wrap {
  position: relative;
  height: 180px;
  width: 100%;
}

#chart {
  width: 100%;
  height: 100%;
  display: block;
  overflow: visible;
}

#chart .line-path {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  animation: drawLine 1.4s cubic-bezier(0.4, 0, 0.2, 1) 0.3s forwards;
}

@keyframes drawLine { to { stroke-dashoffset: 0; } }

#chart .area-path {
  opacity: 0;
  animation: fadeIn 0.8s ease-out 0.8s forwards;
}

@keyframes fadeIn { to { opacity: 1; } }

#chart .pt {
  opacity: 0;
  animation: fadeIn 0.4s ease-out forwards;
}

#chart .extremum-label {
  opacity: 0;
  animation: fadeIn 0.5s ease-out 1.4s forwards;
}

#chart .extremum-dot {
  opacity: 0;
  animation: fadeIn 0.4s ease-out 1.2s forwards;
}

.tooltip {
  position: absolute;
  pointer-events: none;
  background: rgba(11, 14, 24, 0.96);
  border: 1px solid var(--line-2);
  border-radius: 8px;
  padding: 8px 12px;
  font-family: var(--sans);
  transform: translate(-50%, -130%);
  opacity: 0;
  transition: opacity 0.12s;
  backdrop-filter: blur(10px);
  z-index: 10;
  white-space: nowrap;
  box-shadow: 0 6px 20px -8px rgba(0, 0, 0, 0.6);
}

.tooltip.show { opacity: 1; }

.tooltip .hour {
  font-family: var(--mono);
  color: var(--ink-faint);
  font-size: 9px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.tooltip .temp {
  font-family: var(--serif);
  font-size: 22px;
  color: var(--ink);
  margin-top: 1px;
  line-height: 1;
}

.tooltip .temp .unit {
  font-size: 12px;
  color: var(--accent);
  margin-left: 2px;
  font-weight: 400;
}

.state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  text-align: center;
  padding: 40px;
  gap: 16px;
}

.state .icon-circle {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: rgba(240, 168, 104, 0.08);
  border: 1px solid var(--line-2);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  margin-bottom: 4px;
}

.state .icon-circle svg { width: 32px; height: 32px; }

.state .title {
  font-family: var(--serif);
  font-size: 32px;
  font-weight: 400;
  color: var(--ink);
  letter-spacing: -0.01em;
}

.state .desc {
  font-size: 13px;
  color: var(--ink-dim);
  max-width: 520px;
  line-height: 1.6;
}

.state .detail {
  font-family: var(--mono);
  font-size: 10px;
  color: var(--ink-faint);
  margin-top: 4px;
  padding: 6px 12px;
  border: 1px solid var(--line);
  border-radius: 6px;
  letter-spacing: 0.08em;
}

.state .spinner {
  width: 36px;
  height: 36px;
  border: 2px solid var(--line-2);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin 0.9s linear infinite;
}

.state .spinner-text {
  font-family: var(--serif);
  font-size: 20px;
  color: var(--ink-dim);
  margin-top: 4px;
}

@keyframes spin { to { transform: rotate(360deg); } }

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.card > .header,
.card > .main,
.card > .hourly {
  animation: fadeUp 0.55s cubic-bezier(0.2, 0.7, 0.2, 1) both;
}

.card > .header { animation-delay: 0.05s; }
.card > .main { animation-delay: 0.15s; }
.card > .hourly { animation-delay: 0.25s; }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

(function() {
